import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    # Create a lightweight chassis centered at (10.0, 2.0)
    chassis = sandbox.add_beam(
        x=10.0, y=2.0, width=0.5, height=0.2, density=0.5
    )

    # Create two wheels at the base of the chassis
    wheel_radius = 0.2
    wheel_density = 0.5
    wheel1 = sandbox.add_wheel(
        x=9.0, y=1.2, radius=wheel_radius, density=wheel_density
    )
    wheel2 = sandbox.add_wheel(
        x=11.0, y=1.2, radius=wheel_radius, density=wheel_density
    )

    # Attach wheels to the chassis using pivot joints
    joint1 = sandbox.add_joint(
        chassis, wheel1, (9.0, 1.2), type='pivot'
    )
    joint2 = sandbox.add_joint(
        chassis, wheel2, (11.0, 1.2), type='pivot'
    )

    # Set material properties for better traction
    sandbox.set_material_properties(
        chassis, restitution=0.1, friction=0.8
    )
    sandbox.set_material_properties(
        wheel1, restitution=0.1, friction=0.8
    )
    sandbox.set_material_properties(
        wheel2, restitution=0.1, friction=0.8
    )

    return {"body": chassis, "joints": [joint1, joint2]}

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body") if isinstance(agent_body, dict) else None

    # Stop motor once the target is reached
    if torso is not None and torso.position.x > 28.0:
        rotation_speed = 0.0
    else:
        rotation_speed = 10.0  # Adjust based on observed performance

    # Apply opposite motor directions for differential drive
    sandbox.set_motor(joints[0], -rotation_speed, max_torque=2000.0)
    sandbox.set_motor(joints[1], rotation_speed, max_torque=2000.0)

